/**
 * 터미널의 OSC 제목에서 지금 하네스가 맡은 작업 이름만 뽑는다.
 *
 * - `claude`: Claude Code는 `<스피너 글리프> <주제>` 꼴로 제목을 건다(예 `✳ Terminal blind overlay`,
 *   `⠂ Terminal blind overlay`). 글리프를 벗긴 나머지가 주제이며, 기본 제목인 `Claude Code`와
 *   빈 제목은 작업 이름이 아니다.
 * - `pi`: Pi는 `<앱 제목> - <세션 이름> - <폴더>` 꼴이다(예 `π - fix login - dashboard`,
 *   `Pi-Bolt - a - b - dashboard`). 세션 이름은 첫 번째와 마지막 ` - ` 사이라서 중간 전부가
 *   이름이고, 폴더가 없어 세션 이름이 없으면 작업 이름이 아니다.
 */

/** Claude Code 스피너가 쓰는 글리프: 점자 셀(U+2800–U+28FF)과 ✳ 계열 기호. */
const SPINNER = /^[\u2800-\u28FF✳✻✼✽✾✿❋✶✷✸✹✺✵✱]+/;

export function taskTitle(harness: string, raw: string): string | null {
	const title = raw.trim();
	if (!title) return null;

	if (harness === "claude") {
		const topic = title.replace(SPINNER, "").trim();
		if (!topic || topic === "Claude Code" || topic === "Claude") return null;
		return topic;
	}

	if (harness === "pi") {
		const parts = title.split(" - ");
		/* 앱 제목과 폴더 사이에 세션 이름이 있어야 한다. */
		if (parts.length < 3) return null;
		const session = parts.slice(1, -1).join(" - ").trim();
		return session || null;
	}

	return title;
}
